// Uma aprovação por pessoa; quem aprovar primeiro publica.
// Menções do espaço de teste vão só para o Redacted, EXCETO quando quem mencionou foi o CEO (contexto com '|ceo]'):
// aí vai para os dois, para o CEO poder testar sem depender do Redacted. O relatório diário vai para os dois.
// Feedback de reunião (pós-ATA) e aviso de venda ganha ao CS (26/10, sem IA): só o Redacted confere por enquanto.
// 27/10 PILOTO CS/Comercial: respostas a menções em qualquer espaço → só o Redacted (CEO só quando ele mesmo mencionou).
// Modo automático (26/10): publica direto e manda cópia só para o Redacted.
// TRAVA (26/10): mensagem para fora da REDACTED (cliente/terceiro: tipo 'mensagem_externa' ou destino que não é espaço do Chat)
// vai SEMPRE para o CEO e nunca é automática.
const APROVADORES = ['<EMAIL>', '<EMAIL>'];
const CEO = APROVADORES[1];
const ESPACO_TESTE = 'spaces/<SPACE_ID>';
const SO_REDACTED = ['avaliacao_reuniao', 'aviso_venda_cs'];
const MENCOES = ['resposta', 'avaliacao_relatorio'];
const ctx = $('Precisa corrigir?').all().map(i => String(i.json.contexto || ''));
const out = [];
$input.all().forEach((item, i) => {
  const externo = item.json.tipo === 'mensagem_externa' || !String(item.json.space_id || '').startsWith('spaces/');
  const auto = item.json.auto === true && !externo;
  const doCeo = /\|ceo\]/.test(ctx[i] || '');
  const soTeste = item.json.space_id === ESPACO_TESTE && item.json.tipo !== 'relatorio_diario' && !doCeo;
  const mencaoPiloto = MENCOES.includes(item.json.tipo) && !doCeo;
  const soRedacted = !externo && (auto || soTeste || mencaoPiloto || SO_REDACTED.includes(item.json.tipo));
  const lista = externo ? [CEO] : (soRedacted ? APROVADORES.slice(0, 1) : APROVADORES);
  for (const email of lista) out.push({ json: { ...item.json, auto, aprovador_email: email }, pairedItem: { item: i } });
});
return out;

// REVISOR SEM IA: só olha o relatório diário. Outros tipos passam direto.
// 1ª vez com problema: devolve ao agente para corrigir. 2ª vez (contexto começa com [revisado]): segue com os avisos.
const r0 = $('Receber do agente').first().json;
if (r0.tipo !== 'relatorio_diario') return [{ json: { ...r0, corrigir: false } }];
// 27/10: o que vem depois da linha "🔒 SÓ CEO" é a parte reservada (só no privado); o resto é o texto da equipe.
const partes = String(r0.resposta || '').split(/\n[ \t*_]*🔒\s*S[ÓO] CEO[*_:]*[ \t]*/i);
const r = { ...r0, resposta: partes[0].trim(), parte_ceo: partes.slice(1).join('\n').trim() };
const txt = r.resposta;
const probs = [];
if (/o dia foi marcado|dia marcado por|o dia focou|volume moderado|intensas defini/i.test(txt)) probs.push('Frase genérica proibida ("o dia foi marcado por", "o dia focou em"...). Troque por números e fatos.');
const dp = txt.match(/\b(VT|vale[- ]?transporte|vale[- ]?refei\w*|Flash|benef[ií]cios?|sal[aá]rios?|f[eé]rias|atestado|advert[eê]ncia|ponto eletr[oô]nico)\b/gi);
if (dp) probs.push('Possível DP interno da REDACTED (' + [...new Set(dp.map(x => x.toLowerCase()))].join(', ') + '). Se for de funcionário da REDACTED, REMOVA (nem como elogio). Se for de cliente, deixe claro o nome do cliente.');
if (/CEO deveria|sugiro ao CEO|recomend\w* (ao|para o) CEO/i.test(txt)) probs.push('Recomendação dirigida ao CEO: proibido. Fale com a equipe.');
if (txt.length > 3300) probs.push('Texto da equipe passou de 3.300 caracteres (' + txt.length + '). Corte o menos importante (a parte 🔒 SÓ CEO não conta).');
for (let n = 1; n <= 7; n++) if (!new RegExp('\\*' + n + '\\.').test(txt)) probs.push('Falta a seção ' + n + ' do formato.');
// 27/10: o relatório costuma ser aprovado no dia seguinte, então "hoje/amanhã" fica errado. Só data fixa.
const rel = txt.match(/\b(hoje|amanh[ãa])\b/gi);
if (rel) probs.push('Data relativa (' + [...new Set(rel.map(x => x.toLowerCase()))].join(', ') + '): o relatório pode ser publicado no dia seguinte. Use sempre data fixa dd/mm.');
const semPrazo = txt.split('\n').filter(l => l.includes('💡') && !/\d{1,2}\/\d{1,2}|esta semana|at[ée] (sexta|segunda|ter[çc]a|quarta|quinta|o fim)/i.test(l.split('💡')[1] || ''));
if (semPrazo.length) probs.push('Feedback 💡 sem ação com prazo: ' + semPrazo.map(l => l.trim().slice(0, 60)).join(' | ') + '. Cada 💡 precisa de ação concreta + prazo (dd/mm ou esta semana).');
// Decisões repetidas do último relatório aprovado
const secao = (t, a, b) => { const i = t.indexOf('*' + a + '.'); const j = t.indexOf('*' + b + '.'); return i < 0 ? '' : t.slice(i, j > i ? j : undefined); };
const palavras = s => new Set((s.toLowerCase().match(/[a-zà-ÿ0-9]{4,}/g) || []));
const anterior = $('Último relatório aprovado').all().map(i => i.json).find(x => x.message_id && x.message_id !== r.message_id);
if (anterior) {
  const antes = secao(String(anterior.resposta_proposta || ''), 4, 5).split('\n').filter(l => l.includes('•')).map(palavras);
  secao(txt, 4, 5).split('\n').filter(l => l.includes('•')).forEach(l => {
    const p = palavras(l); if (p.size < 3) return;
    for (const a of antes) { let c = 0; p.forEach(w => { if (a.has(w)) c++; }); if (c / p.size >= 0.6) { probs.push('Decisão parece repetida do relatório ' + anterior.message_id + ': "' + l.trim().slice(0, 80) + '". Só entra decisão tomada no dia.'); break; } }
  });
}
const revisado = /^\[revisado\]/i.test(String(r.contexto || ''));
if (probs.length && !revisado) return [{ json: { ...r, corrigir: true, problemas: probs } }];
return [{ json: { ...r, corrigir: false, contexto: String(r.contexto || '') + (probs.length ? ' | ⚠️ Revisor ainda vê: ' + probs.join(' / ') : (revisado ? ' | ✅ Revisor: corrigido' : ' | ✅ Revisor: ok')) } }];

// TRAVA DE PRIVACIDADE SEM IA (26/10): relatório, feedback de reunião e respostas a menções vão para a equipe,
// então não podem citar saída de colaborador nem ex-colaboradores.
// 27/10: + assuntos SENSÍVEIS (inadimplência, distrato, bancos, cortes de custo): no relatório vão para a parte "🔒 SÓ CEO";
// nos outros tipos o aviso 🔒 tira do modo automático e pede conferência.
// 28/10: + não pagou / devendo / em atraso / valores em aberto / acordo / renegociação / alinhamento contratual (caso JS Metal).
// "Pendências em aberto" sozinho NÃO dispara (é título de seção).
const EX_COLABORADORES = ['Redacted', 'Redacted', 'Redacted']; // atualizar quando alguém sair (também em ler_tendencia e cobrança)
const SENSIVEL = /inadimpl\w*|distratos?|rescis[ãa]o|d[ií]vidas?|d[ée]bitos? (com a REDACTED|de honor\w*)|cobran[çc]a judicial|protesto|honor[aá]rios? (em atraso|atrasados?|n[ãa]o pagos?|pendentes?|em aberto|vencidos?)|(boletos?|mensalidades?|parcelas?|pagamentos?|faturas?|valores?) (em aberto|em atraso|atrasad[oa]s?|vencid[oa]s?|n[ãa]o pag[oa]s?)|n[ãa]o (pagou|pagaram|est[áa] pagando|efetuou o pagamento)|devend[oa]|em atraso com|atras\w* (no|nos|com o|com os) pagamentos?|acordo de pagamento|tentativa de acordo|renegocia\w*|alinhamento contratual|operador banc\w*|conta banc\w*|\bIta[úu]\b|Bradesco|Santander|cortes? de (custos?|ferramentas|sistemas)|cancelamento d[oae]s? (sistemas?|ferramentas?|contrato|Data for Company)|rentabilidade/gi;
const item = $input.first().json;
if (!['relatorio_diario', 'avaliacao_reuniao', 'resposta', 'avaliacao_relatorio'].includes(item.tipo)) return [{ json: item }];
const txt = String(item.resposta || '');
const achados = [];
const priv = txt.match(/deslig\w*|demiss\w*|demiti\w*|saiu da (empresa|REDACTED)|encerr\w* (o |seu )?ciclo|[úu]ltimo dia (dela|dele|na REDACTED)|despedid\w*/gi);
if (priv) achados.push('Possível assunto privado de colaborador (' + [...new Set(priv.map(x => x.toLowerCase()))].join(', ') + '). Se for de funcionário da REDACTED, REMOVA: o relatório vai para a equipe toda. Se for de cliente, deixe claro o nome do cliente.');
const ex = EX_COLABORADORES.filter(n => new RegExp('(^|[^\\wÀ-ÿ])' + n + '($|[^\\wÀ-ÿ])', 'i').test(txt));
if (ex.length) achados.push('Cita ex-colaborador (' + ex.join(', ') + '): não cobrar, não dar feedback e não citar. Pendência dele(a) vira "equipe do setor assume".');
const sens = txt.match(SENSIVEL);
if (sens) achados.push('Assunto sensível no texto para a equipe (' + [...new Set(sens.map(x => x.toLowerCase()))].join(', ') + '). ' + (item.tipo === 'relatorio_diario' ? 'Tire do texto da equipe e coloque no FIM, depois de uma linha "🔒 SÓ CEO" (vai só no privado do CEO). No texto da equipe, no máximo "N clientes em risco de retenção — detalhes com o CEO".' : 'Confira se pode sair no grupo.'));
if (!achados.length) return [{ json: item }];
// Só o relatório diário (agente) pode refazer; os outros tipos só avisam o aprovador.
const revisado = item.tipo !== 'relatorio_diario' || /^\[revisado\]/i.test(String(item.contexto || ''));
if (!revisado) return [{ json: { ...item, corrigir: true, problemas: [...(item.problemas || []), ...achados] } }];
return [{ json: { ...item, corrigir: false, contexto: '🔒 PRIVACIDADE — confira antes de aprovar: ' + achados.join(' / ') + ' | ' + String(item.contexto || '') } }];

// Resumo de custo do Zezinho só para o Redacted. Relatório = valor ESTIMADO (R$ 0,20 no Gemini 3.5 Flash desde 26/10;
// calibrar com o AI Studio depois de 1 semana); menções e feedback de reunião = valor real medido.
const CREDITO = 70;
const EST_RELATORIO = 0.2;
const rows = $input.all().map(i => i.json).filter(r => r.custo_brl != null);
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
const soma = l => l.reduce((s, r) => s + Number(r.custo_brl || 0), 0);
const brl = v => 'R$ ' + v.toFixed(2).replace('.', ',');
const mes = soma(rows);
const conteudo = [
  '• Relatório de hoje: ~' + brl(EST_RELATORIO) + ' (estimado)',
  '• Hoje (relatório + menções + reuniões): ' + brl(soma(rows.filter(r => r.dia === hoje))),
  '• Mês: ' + brl(mes) + ' de ' + brl(CREDITO) + ' (' + (mes / CREDITO * 100).toFixed(1).replace('.', ',') + '%)',
  '_Só Zezinho. Valor real (com ATA e cartões): AI Studio → Gasto._'
].join('\n');
return [{ json: { titulo: '💰 Custo de IA — ' + $now.setZone('America/Sao_Paulo').toFormat('dd/MM'), conteudo } }];

// JUIZ (26/10): 1 chamada barata ao Gemini dá nota 0-10 ao texto, com base nas regras do gestor.
// Critérios por tipo: relatório diário, feedback de reunião e resposta a menção/avaliação.
// 27/10: mais exigente (conselho genérico, repetição, datas relativas, assunto sensível) — mesma chamada, sem custo extra.
const item = $('Trava de privacidade').first().json;
const tipo = item.tipo;
const reuniao = tipo === 'avaliacao_reuniao';
const relatorio = tipo === 'relatorio_diario';
const regras = $input.all().map(i => i.json)
  .filter(r => r.descricao && (relatorio || !/relat[óo]rio di[aá]rio|relat[óo]rio de gest/i.test(String(r.titulo || '') + ' ' + String(r.descricao || '').slice(0, 80))))
  .map(r => '- ' + String(r.descricao).slice(0, 500)).join('
');
const PRIV = 'Nada privado: desligamento, saída, saúde, salário ou assunto pessoal de colaborador; nada de ex-colaboradores; nada de valores, CPF ou CNPJ de cliente (falha = nota no máximo 4).';
const SENS = 'Nada de inadimplência, distrato, dívida, bancos, cortes de custo ou rentabilidade (o texto vai para a equipe toda; isso é assunto do CEO): falha = nota no máximo 5.';
const criterios = relatorio
  ? `1. Segue TODAS as regras do gestor abaixo (regra descumprida = nota no máximo 6).
2. Cada risco, pendência ou decisão tem fonte [espaço, hora, pessoa].
3. ${PRIV}
4. ${SENS}
5. Sem frases genéricas; todo 💡 é ação concreta com prazo em data fixa (dd/mm). "hoje"/"amanhã" = nota no máximo 7.
6. Não repete o mesmo cliente ou assunto em duas seções sem fato novo (repetição = nota no máximo 7).
7. Útil para um gestor: aponta o que falta, quem faz e até quando (cita o POP quando couber), e não só resume. Elogio vago (ex.: "organização das salas") não conta.`
  : reuniao
  ? `1. Segue as regras do gestor abaixo.
2. Tudo vem da reunião (nada inventado); não precisa citar hora nem espaço.
3. ${PRIV}
4. ${SENS}
5. 💡 são ações práticas da EQUIPE DA REDACTED para conduzir melhor a próxima reunião, tiradas do que aconteceu NESTA reunião. Conselho genérico que serviria para qualquer reunião (ex.: "enviar a pauta com antecedência", "fechar cada assunto com responsável e prazo") sem a reunião ter mostrado esse problema = nota no máximo 7.
6. Próximos passos têm responsável; "definir prazo" é aceitável quando a reunião não definiu.
7. Curto, claro e construtivo; elogio vago ("liderança atuante", "boa condução") sem fato concreto não conta.`
  : `1. Responde EXATAMENTE ao que foi perguntado (veja o CONTEXTO), sem desviar de assunto.
2. Se afirma um fato (data, valor, regra, nome), diz de onde veio (chat de dd/mm, ATA, POP); fato sem fonte ou de OUTRO assunto/cliente = nota no máximo 5.
3. Se não sabe, diz claramente e indica quem pode saber (isso é bom, não tire nota).
4. ${PRIV}
5. ${SENS}
6. Curto, direto e educado; segue as regras do gestor abaixo.`;
const oQue = relatorio ? 'um RELATÓRIO DIÁRIO DE GESTÃO dos chats' : reuniao ? 'um FEEDBACK DE REUNIÃO' : 'uma RESPOSTA do gestor a uma pergunta/menção da equipe';
const prompt = `Você é o revisor de qualidade do Zezinho, gestor de IA da Redacted Contabilidade (REDACTED). Avalie ${oQue} que será publicado no chat interno.

Dê nota de 0 a 10 pelos critérios:
${criterios}
10 = impecável (raro); 9 = pode publicar sem mexer; 8 = bom, com detalhe a melhorar; abaixo de 8 = precisa corrigir. Seja exigente, mas não tire nota por algo que o critério não pede.

REGRAS DO GESTOR:
${regras || '(nenhuma)'}

CONTEXTO (o que foi pedido):
${String(item.contexto || '').slice(0, 800)}

TEXTO:
${String(item.resposta || '')}

Responda SOMENTE JSON: {"nota": número, "problemas": [até 5 frases curtas, cada uma dizendo o que corrigir]}`;
return [{ json: { body: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0, responseMimeType: 'application/json' } } } }];

// Nota < 8 no relatório diário (1ª vez) → volta ao agente. Os outros tipos e a 2ª vez → seguem com a nota para o aprovador.
// 28/10: leitura tolerante (cercas ```json, texto antes/depois do JSON); se o JSON vier quebrado, pega só o número de "nota".
const item = $('Trava de privacidade').first().json;
let j = {};
let raw = '';
try { raw = ($input.first().json.candidates || [])[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
const limpo = String(raw).replace(/```(?:json)?/gi, '').trim();
try { j = JSON.parse(limpo); } catch (e) {
  try { j = JSON.parse(limpo.slice(limpo.indexOf('{'), limpo.lastIndexOf('}') + 1)); } catch (e2) {
    const m = limpo.match(/"nota"\s*:\s*(\d+(?:\.\d+)?)/);
    if (m) j = { nota: Number(m[1]), problemas: [] };
  }
}
const nota = Number(j.nota);
if (!Number.isFinite(nota)) return [{ json: { ...item, contexto: String(item.contexto || '') + ' | ⚖️ Juiz: indisponível' } }];
const probs = (Array.isArray(j.problemas) ? j.problemas : []).slice(0, 5).map(String);
const revisado = item.tipo !== 'relatorio_diario' || /^\[revisado\]/i.test(String(item.contexto || ''));
if (nota < 8 && !revisado) return [{ json: { ...item, corrigir: true, problemas: [...(item.problemas || []), ...probs.map(p => 'Juiz de qualidade (nota ' + nota + '/10): ' + p)] } }];
// Avaliação de relatório de pessoa usa "nota" para a nota da PESSOA: não sobrescreve.
const manterNota = item.tipo === 'avaliacao_relatorio';
return [{ json: { ...item, ...(manterNota ? {} : { nota }), contexto: '⚖️ Juiz: ' + nota + '/10' + (nota < 8 ? ' ⚠️ CONFIRA' : '') + (probs.length ? ' — ' + probs.join(' / ') : '') + ' | ' + String(item.contexto || '') } }];

// PUBLICAÇÃO AUTOMÁTICA — 27/10 (decisão do Redacted): TUDO automático, com freios.
// - Juiz >= 8 (nota do juiz gravada no contexto) e sem aviso 🔒 (privacidade/sensível) nem do revisor.
// - Nenhuma rejeição (ou 👎) nas últimas 3 decisões do mesmo tipo: um 👎 volta o tipo para aprovação até 3 aprovações seguidas.
// - Aviso de venda ganha ao CS (sem IA, dados do RD): sempre automático.
// - 27/10: resposta no PRIVADO DO CEO (só ele lê) sai direto — não faz sentido pedir aprovação ao CEO da resposta para ele mesmo.
// Mensagem para fora da REDACTED nunca é automática (trava em Aprovadores). Cada publicação automática manda cópia 👍/👎 ao Redacted.
const TIPOS = ['relatorio_diario', 'avaliacao_reuniao', 'resposta', 'avaliacao_relatorio'];
const SEM_IA = ['aviso_venda_cs'];
const DM_CEO = 'spaces/<SPACE_ID>';
const JANELA = 3;
const salvos = $('Salvar avaliação pendente').all();
const atual = $('Precisa corrigir?').first().json;
const idAtual = salvos[0] && salvos[0].json.id;
const hist = $input.all().map(i => i.json)
  .filter(r => r.id && r.id !== idAtual && ['aprovado', 'publicado_auto', 'rejeitado'].includes(r.status));
const semRejeicao = hist.slice(0, JANELA).every(r => r.status !== 'rejeitado');
const ctx = String(atual.contexto || '');
const m = ctx.match(/⚖️ Juiz: (\d+(?:[.,]\d+)?)/);
const juiz = m ? Number(m[1].replace(',', '.')) : NaN;
const limpo = !ctx.includes('🔒') && !ctx.includes('Revisor ainda vê');
const privadoCeo = atual.space_id === DM_CEO;
const auto = privadoCeo || SEM_IA.includes(atual.tipo) || (TIPOS.includes(atual.tipo) && semRejeicao && juiz >= 8 && limpo);
return salvos.map((s, i) => ({ json: { ...s.json, auto }, pairedItem: { item: i } }));

// 27/10: a parte "🔒 SÓ CEO" do relatório não vai para o Geral: sai só no privado.
// 28/10: Redacted validou o formato → vai também para o CEO.
const ENVIAR_AO_CEO = true;
const it = $('Precisa corrigir?').first().json;
const p = String(it.parte_ceo || '').trim();
if (it.tipo !== 'relatorio_diario' || !p) return [];
const texto = '🔒 *Zezinho — parte reservada do relatório* (' + (it.titulo_relatorio || '') + ')\n_Não vai para o Geral._\n\n' + p;
const emails = ['<EMAIL>'].concat(ENVIAR_AO_CEO ? ['<EMAIL>'] : []);
return emails.map(email => ({ json: { email, texto } }));
